// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue } from '@skyramp/skyramp';
import { getConfig, getSite } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:2368");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Ghost " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const configGetResponse = await getConfig(client, headers);

    expect(getValue(configGetResponse, "config.version"), 'config.version').toMatch(/^\d+\.\d+/);
    expect(getValue(configGetResponse, "config.environment"), 'config.environment').not.toBeNull();
    expect(getValue(configGetResponse, "config.database"), 'config.database').not.toBeNull();

    const siteGetResponse = await getSite(client, headers);

    expect(getValue(siteGetResponse, "site.url"), 'site.url').toBe("http://localhost:2368/");
    expect(getValue(siteGetResponse, "site.locale"), 'site.locale').toBe("en");
    expect(getValue(siteGetResponse, "site.version"), 'site.version').toMatch(/^\d+\.\d+/);
    expect(getValue(configGetResponse, "config.version").startsWith(getValue(siteGetResponse, "site.version")), 'config.version shares the site.version prefix').toBe(true);
});
